                .frame(width: 8, height: 8)
            Text(model.status)
                .font(.system(size: 13, weight: .medium))
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 6)
        .background(Color.white.opacity(0.08))
        .cornerRadius(7)
    }

    @ViewBuilder
    private var content: some View {
        if model.views.isEmpty {
            VStack(spacing: 12) {
                ProgressView()
                    .progressViewStyle(.circular)
                    .scaleEffect(0.85)
                Text(model.status)
                    .foregroundColor(.white.opacity(0.7))
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            let view = model.views[min(model.selectedViewIndex, model.views.count - 1)]

            ScrollView {
                LazyVGrid(
                    columns: [GridItem(.adaptive(minimum: 380, maximum: 560), spacing: 16, alignment: .top)],
                    alignment: .leading,
                    spacing: 16
                ) {
                    ForEach(view.cards) { card in
                        CardRenderer(card: card)
                            .environmentObject(model)
                    }
                }
                .padding(18)
            }
        }
    }

    private func errorBanner(_ errorMessage: String) -> some View {
        HStack {
            Image(systemName: "exclamationmark.triangle.fill")
                .foregroundColor(.yellow)
            Text(errorMessage)
                .font(.system(size: 13))
                .lineLimit(2)
            Spacer()
        }
        .padding(.horizontal, 22)
        .padding(.vertical, 10)
        .background(Color.yellow.opacity(0.12))
    }
}

import Foundation

public enum HomeAssistantWebSocketError: Error, Equatable {
    case invalidURL
    case invalidMessage
    case authenticationFailed(String)
    case commandFailed(String)
    case disconnected
}

public final class HomeAssistantWebSocketClient {
    private let configuration: HomeAssistantConfiguration
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private var nextID = 1

    public init(configuration: HomeAssistantConfiguration, session: URLSession = .shared) {
        self.configuration = configuration
        self.session = session
    }

    public func connect() async throws {
        let url = try webSocketURL(from: configuration.baseURL)
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()

        let authRequired = try await receiveDictionary()
        guard authRequired["type"] as? String == "auth_required" else {
            throw HomeAssistantWebSocketError.invalidMessage
        }

        try await send([
            "type": "auth",
            "access_token": configuration.accessToken,
        ])

        while true {
            let response = try await receiveDictionary()
            switch response["type"] as? String {
            case "auth_ok":
                return
            case "auth_invalid":
                let message = response["message"] as? String ?? "Authentication rejected"
                throw HomeAssistantWebSocketError.authenticationFailed(message)
            default:
                continue
            }
        }
    }

    public func disconnect() {
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }

    public func fetchLovelaceConfig() async throws -> LovelaceConfig {
        let result = try await sendCommand(type: "lovelace/config")
        let data = try JSONSerialization.data(withJSONObject: result)
        return try JSONDecoder().decode(LovelaceConfig.self, from: data)
    }

    public func subscribeToStateChanges() async throws {
        _ = try await sendCommand(
            type: "subscribe_events",
            fields: ["event_type": "state_changed"]
        )
    }

    public func receiveStateChanges(_ onState: @escaping (HAState) -> Void) async throws {
        while true {
            let message = try await receiveDictionary()
            guard
                message["type"] as? String == "event",
                let event = message["event"] as? [String: Any],
                let data = event["data"] as? [String: Any],
                let newState = data["new_state"] as? [String: Any]
            else {
                continue
            }

            let encoded = try JSONSerialization.data(withJSONObject: newState)
            let state = try JSONDecoder().decode(HAState.self, from: encoded)
            onState(state)
        }
    }

    private func sendCommand(type: String, fields: [String: Any] = [:]) async throws -> Any {
        guard task != nil else {
            throw HomeAssistantWebSocketError.disconnected
        }

        let id = nextID
        nextID += 1

        var payload = fields
        payload["id"] = id
        payload["type"] = type

        try await send(payload)

        while true {
            let response = try await receiveDictionary()
            guard response["id"] as? Int == id else {
                continue
            }

            if response["success"] as? Bool == true, let result = response["result"] {
                return result
            }

            if
                let error = response["error"] as? [String: Any],
                let message = error["message"] as? String
            {
                throw HomeAssistantWebSocketError.commandFailed(message)
            }

            throw HomeAssistantWebSocketError.invalidMessage
        }
    }

    private func send(_ object: [String: Any]) async throws {
        guard let task = task else {
            throw HomeAssistantWebSocketError.disconnected
        }

        let data = try JSONSerialization.data(withJSONObject: object)
        guard let string = String(data: data, encoding: .utf8) else {
            throw HomeAssistantWebSocketError.invalidMessage
        }

        try await withCheckedThrowingContinuation { continuation in
            task.send(.string(string)) { error in
                if let error = error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume(returning: ())
                }
            }
        }
    }

    private func receiveDictionary() async throws -> [String: Any] {
        guard let task = task else {
            throw HomeAssistantWebSocketError.disconnected
        }

        let message = try await withCheckedThrowingContinuation { continuation in
            task.receive { result in
                continuation.resume(with: result)
            }
        }

        let data: Data
        switch message {
        case let .string(string):
            data = Data(string.utf8)
        case let .data(rawData):
            data = rawData
        @unknown default:
            throw HomeAssistantWebSocketError.invalidMessage
        }

        guard let object = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw HomeAssistantWebSocketError.invalidMessage
        }
        return object
    }

    private func webSocketURL(from baseURL: URL) throws -> URL {
        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw HomeAssistantWebSocketError.invalidURL
        }

        switch components.scheme {
        case "https":
            components.scheme = "wss"
        case "http":
            components.scheme = "ws"
        default:
            throw HomeAssistantWebSocketError.invalidURL
        }

        let basePath = components.path.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        components.path = "/" + ([basePath, "api", "websocket"].filter { !$0.isEmpty }.joined(separator: "/"))

        guard let url = components.url else {
            throw HomeAssistantWebSocketError.invalidURL
        }
        return url
    }
}

import Foundation
import NativeHACore

@MainActor
final class DashboardViewModel: ObservableObject {
    @Published var selectedViewIndex = 0
    @Published var views: [LovelaceView] = []
    @Published var states: [String: HAState] = [:]
    @Published var histories: [String: [HAHistorySeries]] = [:]
    @Published var status = "Starting"
    @Published var errorMessage: String?
    @Published var activeBaseURL: URL?

    private var restClient: HomeAssistantRESTClient?
    private var webSocketClient: HomeAssistantWebSocketClient?
    private var hasStarted = false

    func start() {
        guard !hasStarted else {
            return
        }
        hasStarted = true

        Task {
            await load()
        }
    }

    func displayName(for entityID: String) -> String {
        if
            let nameValue = states[entityID]?.attributes["friendly_name"],
            case let .string(name) = nameValue
        {
            return name
        }

        return entityID
            .split(separator: ".")
            .last
            .map { String($0).replacingOccurrences(of: "_", with: " ").capitalized }
            ?? entityID
    }

    func displayState(for entityID: String) -> String {
        guard let state = states[entityID] else {
            return "Unavailable"
        }

        var value = state.state
        if let numeric = Double(value) {
            value = formatNumber(numeric)
        }

        if
            let unitValue = state.attributes["unit_of_measurement"],
            case let .string(unit) = unitValue,
            !unit.isEmpty
        {
            return "\(value) \(unit)"
        }

        return value.replacingOccurrences(of: "_", with: " ")
    }

    func isOn(entityID: String) -> Bool {
        states[entityID]?.state == "on"
    }

    func canToggle(entityID: String) -> Bool {
        switch domain(for: entityID) {
        case "switch", "fan", "input_boolean", "automation":
            return true
        default:
            return false
        }
    }

    func setPower(entityID: String, isOn: Bool) {
        guard let restClient = restClient else {
            return
        }

        let service = isOn ? "turn_on" : "turn_off"
        let domain = domain(for: entityID)
        applyOptimisticState(entityID: entityID, state: isOn ? "on" : "off")

        Task {
            do {
                _ = try await restClient.callService(
                    domain: domain,
                    service: service,
                    data: ["entity_id": .string(entityID)]
                )
            } catch {
                self.errorMessage = "Service call failed for \(entityID): \(error.localizedDescription)"
            }
        }
    }

    func refreshHistories() {
        Task {
            await loadHistories()
        }
    }

    private func load() async {
        do {
            status = "Reading token"
            let token = try loadToken()

            status = "Connecting"
            let connection = try await firstWorkingConnection(token: token)
            activeBaseURL = connection.baseURL
            restClient = connection.restClient

            status = "Loading states"
            let stateList = try await connection.restClient.fetchStates()
            states = Dictionary(uniqueKeysWithValues: stateList.map { ($0.entityId, $0) })

            status = "Loading dashboard"
            let webSocket = HomeAssistantWebSocketClient(configuration: connection.configuration)
            try await webSocket.connect()
            let config = try await webSocket.fetchLovelaceConfig()
            views = config.views
            webSocketClient = webSocket

            await loadHistories()

            status = "Live"
            try await webSocket.subscribeToStateChanges()
            Task.detached { [weak self, webSocket] in
                do {
                    try await webSocket.receiveStateChanges { state in
                        Task { @MainActor in
                            self?.states[state.entityId] = state
                        }
                    }
                } catch {
                    Task { @MainActor in
                        self?.status = "Disconnected"
                        self?.errorMessage = "WebSocket disconnected: \(error.localizedDescription)"
                    }
                }
            }
        } catch {
            status = "Error"
            errorMessage = error.localizedDescription
        }
    }

    private func loadHistories() async {
        guard let restClient = restClient else {
            return
        }

        do {
            let requests = historyRequests()
            var nextHistories: [String: [HAHistorySeries]] = histories

            for request in requests {
                nextHistories[request.key] = try await restClient.fetchHistory(
                    entityIDs: request.entityIDs,
                    hoursToShow: request.hoursToShow
                )
            }

            histories = nextHistories
        } catch {
            errorMessage = "History refresh failed: \(error.localizedDescription)"
        }
    }

    private func firstWorkingConnection(token: String) async throws -> Connection {
        var lastError: Error?

        for baseURL in AppConfig.baseURLs {
            let configuration = HomeAssistantConfiguration(baseURL: baseURL, accessToken: token)
            let client = HomeAssistantRESTClient(configuration: configuration)

            do {
                _ = try await client.fetchConfig()
                return Connection(
                    baseURL: baseURL,
                    configuration: configuration,
                    restClient: client
                )
            } catch {
                lastError = error
            }
        }

        throw lastError ?? URLError(.cannotConnectToHost)
    }

    private func loadToken() throws -> String {
        try String(contentsOfFile: AppConfig.tokenFilePath, encoding: .utf8)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func historyRequests() -> [HistoryRequest] {
        var requests: [HistoryRequest] = []
        for view in views {
            collectHistoryRequests(from: view.cards, into: &requests)
        }
        return requests.removingDuplicates()
    }

    private func collectHistoryRequests(from cards: [LovelaceCard], into requests: inout [HistoryRequest]) {
        for card in cards {
            if card.type == "history-graph" {
                let entities = card.entities?.compactMap(\.entity) ?? []
                if !entities.isEmpty {
                    let hours = card.hoursToShow ?? 1
                    requests.append(HistoryRequest(entityIDs: entities, hoursToShow: hours))
                }
            }

            if let nestedCards = card.cards {
                collectHistoryRequests(from: nestedCards, into: &requests)
            }
        }
    }

    private func domain(for entityID: String) -> String {
        String(entityID.split(separator: ".").first ?? "")
    }

    private func applyOptimisticState(entityID: String, state: String) {
        guard let old = states[entityID] else {
            return
        }

        states[entityID] = HAState(
            entityId: old.entityId,
            state: state,
            attributes: old.attributes,
            lastChanged: old.lastChanged,
            lastUpdated: old.lastUpdated
        )
    }

    private func formatNumber(_ value: Double) -> String {
        if abs(value) >= 100 {
            return String(format: "%.0f", value)
        }

        if abs(value) >= 10 {
            return String(format: "%.1f", value)
        }

        return String(format: "%.2f", value)
    }
}

private struct Connection {
    let baseURL: URL
    let configuration: HomeAssistantConfiguration
    let restClient: HomeAssistantRESTClient
}

struct HistoryRequest: Hashable {
    let entityIDs: [String]
    let hoursToShow: Int

    var key: String {
        "\(hoursToShow):\(entityIDs.joined(separator: ","))"
    }
}

private extension Array where Element == HistoryRequest {
    func removingDuplicates() -> [HistoryRequest] {
        var seen = Set<String>()
        return filter { request in
            seen.insert(request.key).inserted
        }
    }
}

