}

func color(for entityID: String) -> Color {
    let palette: [Color] = [
        Color.cyan,
        Color.green,
        Color.yellow,
        Color.orange,
        Color.pink,
        Color.purple,
        Color.blue,
        Color.mint,
    ]

    let hash = abs(entityID.unicodeScalars.reduce(0) { ($0 &* 31) &+ Int($1.value) })
    return palette[hash % palette.count]
}

