struct Sparkline: View {
    let series: [HAHistorySeries]

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color.black.opacity(0.22))

                Path { path in
                    let height = geometry.size.height
                    for index in 1..<4 {
                        let y = height * CGFloat(index) / 4
                        path.move(to: CGPoint(x: 0, y: y))
                        path.addLine(to: CGPoint(x: geometry.size.width, y: y))
                    }
                }
                .stroke(Color.white.opacity(0.07), lineWidth: 1)

                ForEach(series) { item in
                    SparklinePath(series: item)
                        .stroke(color(for: item.entityID), lineWidth: 2)
                }
            }
        }
    }
}

struct SparklinePath: Shape {
    let series: HAHistorySeries

    func path(in rect: CGRect) -> Path {
        let values = sampledValues(from: series.points)
        guard values.count > 1 else {
            return Path()
        }

        let minValue = values.min() ?? 0
        let maxValue = values.max() ?? 1
        let range = max(maxValue - minValue, 0.0001)

        var path = Path()
        for (index, value) in values.enumerated() {
            let x = rect.minX + rect.width * CGFloat(index) / CGFloat(values.count - 1)
            let normalized = (value - minValue) / range
            let y = rect.maxY - rect.height * CGFloat(normalized)
            let point = CGPoint(x: x, y: y)

            if index == 0 {
                path.move(to: point)
            } else {
                path.addLine(to: point)
            }
        }

        return path
    }

    private func sampledValues(from points: [HAHistoryPoint]) -> [Double] {
        let values = points.compactMap { point -> Double? in
            if point.state == "on" {
                return 1
            }
            if point.state == "off" {
                return 0
            }
            return Double(point.state)
        }

        guard values.count > 420 else {
            return values
        }

        let stride = max(values.count / 420, 1)
        return values.enumerated().compactMap { index, value in
            index % stride == 0 ? value : nil
        }
    }
}

