struct DomainIcon: View {
    let entityID: String

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 5)
                .fill(color.opacity(0.13))
            Image(systemName: symbol)
                .font(.system(size: 16, weight: .semibold))
                .foregroundColor(color)
        }
    }

    private var domain: String {
        String(entityID.split(separator: ".").first ?? "")
    }

    private var symbol: String {
        switch domain {
        case "sensor":
            if entityID.contains("temperature") {
                return "thermometer"
            }
            if entityID.contains("humidity") {
                return "drop.fill"
            }
            return "waveform.path.ecg"
        case "binary_sensor":
            return "circle"
        case "switch", "input_boolean":
            return "power"
        case "fan":
            return "fanblades"
        case "person", "device_tracker":
            return "person.fill"
        case "weather":
            return "cloud.sun.fill"
        case "climate":
            return "thermometer.medium"
        default:
            return "smallcircle.filled.circle"
        }
    }

    private var color: Color {
        switch domain {
        case "sensor":
            return Color(red: 0.2, green: 0.58, blue: 0.86)
        case "binary_sensor":
            return Color(red: 0.2, green: 0.58, blue: 0.86)
        case "switch", "input_boolean":
            return Color(red: 0.2, green: 0.72, blue: 0.38)
        case "fan":
            return Color(red: 0.2, green: 0.58, blue: 0.86)
        case "person", "device_tracker":
            return Color(red: 0.2, green: 0.58, blue: 0.86)
