        Color(red: 0.66, green: 0.42, blue: 0.92),
        Color(red: 0.45, green: 0.76, blue: 0.32),
    ]

    let hash = abs(entityID.unicodeScalars.reduce(0) { ($0 &* 31) &+ Int($1.value) })
    return palette[hash % palette.count]
}

